USE wad_restaurant;

CREATE TEMPORARY TABLE IF NOT EXISTS vietnamese_customer_dishes (
  name VARCHAR(255) NOT NULL,
  price DECIMAL(10, 2) NOT NULL,
  description TEXT NULL,
  image VARCHAR(500) NULL,
  category VARCHAR(100) NULL
);

TRUNCATE TABLE vietnamese_customer_dishes;


SELECT vcd.name, vcd.price, vcd.description, vcd.image, vcd.category
FROM vietnamese_customer_dishes AS vcd
WHERE NOT EXISTS (
  SELECT 1
  FROM foods AS f
  WHERE f.name = vcd.name
);

DROP TEMPORARY TABLE vietnamese_customer_dishes;
